// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(address actor, address newLog) public {
        vm.assume(actor != address(0));
        vm.assume(newLog != address(0));
        // finalize configuration: after Initialized(), the guard makes
        // SetLogFile permanently revert in the reference contract
        vm.prank(actor);
        c.Initialized();
        bool ok;
        vm.prank(actor);
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }
        // GENERAL RULE: after initialization, SetLogFile must ALWAYS revert
        assertTrue(!ok);
    }
}
